 readonly List<PrimitiveStrike> primitiveStrikes=new();readonly List<BowFlight> bowFlights=new();double primitiveSwing=-10;
 void SelectCombatClass(int category){var ids=game.Craft.Weapons.Where(id=>(category==0?ExpeditionGame.IsMelee(id):category==1?ExpeditionGame.IsBow(id):ExpeditionGame.IsGun(id))&&game.WeaponGate(id)=="Ready").ToArray();if(ids.Length==0){game.Notice=category==2?"Guns unlock at character level 2 and tier 2 materials":"Craft a weapon in this class / K";return;}int next=ids[(Array.IndexOf(ids,game.Craft.Weapon)+1)%ids.Length];axeEquipped=false;reloadClock=0;if(!CoopRequest("equip",next.ToString()))game.Change(()=>game.Equip(next));BuildGun();}
 void BeginMelee(){if(shotClock>0||reloadClock>0)return;primitiveSwing=Time.GetTicksMsec()/1000.0;if(CoopRequest("shoot")){shotClock=game.SoulMeleeDelay;Sound(4);return;}int id=game.Craft.Weapon;if(game.Stamina<game.MeleeCost){game.Notice="Catch your breath / insufficient stamina";return;}if(ExpeditionGame.IsPoweredSaw(id)&&game.Craft.Fuel<=0){game.Notice="Chainsaw empty / craft fuel at workshop 2";return;}if(id==27&&game.Craft.Stock(4)<1){game.Notice="Chain sword needs energy cells";return;}if(!game.Change(()=>{game.Stamina-=game.MeleeCost;if(ExpeditionGame.IsPoweredSaw(id)&&Random.Shared.Next(100)>=game.UpgradePower(3))game.Craft.Fuel--;if(id==27)game.Craft.SpendAmmo(4,1);} ))return;shotClock=game.SoulMeleeDelay;primitiveStrikes.Add(new(){Owner=coopActor,Weapon=id,From=camera.GlobalPosition,Direction=-camera.GlobalBasis.Z,Delay=id==17?.06:.19});Noise((ExpeditionGame.IsPoweredSaw(id)?65:5)*game.SoulWeaponNoise*game.WeaponNoise);Sound(4);}
 void PrimitiveOwner(long id,Action act){if(id==0)act();else if(coopActors.TryGetValue(id,out var actor))WithCoopActor(actor,act);}
 void WeaponContact(Infected enemy,Vector3 point,Vector3 direction,bool head,int source=-1){int weapon=source<0?game.Craft.Weapon:source;var skill=game.ProficiencyFor(weapon);if(IsMillBoss(enemy.Id))millParticipants.Add(game);MegaWeakpoint(enemy,point,game.DamageFor(weapon,head));enemy.Hp-=game.DamageFor(weapon,head)*InfectedResistance(enemy,head)*(IsMillBoss(enemy.Id)?MillDamageMultiplier(enemy,point):1);EnemyImpact(enemy,point,direction,head?12:7);ReactEnemyHit(enemy,head);if(weapon==27&&!IsSammy(enemy.Id))ChainElectric(enemy,point);ConfirmHit(head);skill.Gain(head?8:4);game.Notice=game.WeaponClass+" / "+(head?"HEADSHOT":"HIT");if(enemy.Hp<=0){skill.Gain(18);KillEnemy(enemy);}game.Persist();}
 void ResolveMelee(PrimitiveStrike attack){if(game.Craft.Weapon!=attack.Weapon)return;float reach=(float)ExpeditionGame.WeaponReach(attack.Weapon);var side=attack.Direction.Cross(Vector3.Up).Normalized();var struck=new HashSet<string>();bool sword=ExpeditionGame.IsSword(attack.Weapon);foreach(float offset in sword?new[]{0f,-.22f,.22f,-.45f,.45f}:new[]{0f,-.16f,.16f,-.30f,.30f}){var dir=(attack.Direction+side*offset).Normalized();var q=PhysicsRayQueryParameters3D.Create(attack.From,attack.From+dir*reach);q.Exclude=new(){player.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);if(hit.Count==0)continue;var collider=hit["collider"].AsGodotObject() as Node;var point=(Vector3)hit["position"];var enemy=infected.Find(e=>e.Body==collider);if(enemy!=null){if(struck.Add(enemy.Id)){WeaponContact(enemy,point,dir,false);Noise(10);}if(!sword||struck.Count>=3)return;continue;}if(IsFamilyShelf(collider)){DamageFamilyShelf((int)game.Damage(false));return;}if(offset==0)ImpactParticles(point,new(.55f,.48f,.32f),4,.025f);}}
 void LaunchArrow(){if(coopCheck)GD.Print($"ARROW / owner {coopActor} weapon {game.Craft.Weapon} origin {camera.GlobalPosition} aim {-camera.GlobalBasis.Z}");var velocity=-camera.GlobalBasis.Z*(float)((game.Craft.Weapon==32?60:game.Craft.Weapon==19?55:38)*game.SoulArrowSpeed);var pos=camera.GlobalPosition-camera.GlobalBasis.Z*.45f;AddBowFlight(pos,velocity,coopActor,game.Craft.Weapon);if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopBowFlight),pos,velocity,game.Craft.Weapon);}
 void AddBowFlight(Vector3 pos,Vector3 velocity,long owner,int weapon){Node3D mesh=null;if(DisplayServer.GetName()!="headless"){mesh=new Node3D{Position=pos};AddChild(mesh);Tube(mesh,Vector3.Zero,new(0,0,.65f),.008f,Wood);Bevel(mesh,new(0,0,-.04f),new(.035f,.02f,.08f),Steel);}bowFlights.Add(new(){Position=pos,Velocity=velocity,Owner=owner,Weapon=weapon,Mesh=mesh,Room=dungeon?.Id??""});}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopBowFlight(Vector3 pos,Vector3 velocity,int weapon){if(CoopClient)AddBowFlight(pos,velocity,-1,weapon);}
 void TickPrimitiveCombat(double dt){for(int i=primitiveStrikes.Count-1;i>=0;i--){var a=primitiveStrikes[i];a.Delay-=dt;if(a.Delay>0)continue;primitiveStrikes.RemoveAt(i);PrimitiveOwner(a.Owner,()=>ResolveMelee(a));}
 for(int i=bowFlights.Count-1;i>=0;i--){var a=bowFlights[i];a.Life-=dt;var next=a.Position+a.Velocity*(float)dt;a.Velocity+=Vector3.Down*9*(float)dt;var q=PhysicsRayQueryParameters3D.Create(a.Position,next);q.Exclude=new Godot.Collections.Array<Rid>(MillPlayers().Select(p=>p.Body.GetRid()));var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);bool remove=a.Life<=0||a.Room!=(dungeon?.Id??"")||hit.Count>0;if(hit.Count>0&&!CoopClient){var enemy=infected.Find(e=>e.Body==hit["collider"].AsGodotObject());if(enemy!=null)PrimitiveOwner(a.Owner,()=>{var point=(Vector3)hit["position"];WeaponContact(enemy,point,a.Velocity.Normalized(),Species(enemy.Id)==""&&point.Y-enemy.Body.Position.Y>EnemyHeadHeight(enemy),a.Weapon);});}if(remove){if(coopCheck&&!CoopClient)GD.Print($"ARROW RESULT / owner {a.Owner} hit {(hit.Count>0?hit["collider"].AsGodotObject().ToString():"expired")} position {a.Position}");a.Mesh?.QueueFree();bowFlights.RemoveAt(i);continue;}a.Position=next;if(a.Mesh!=null){a.Mesh.Position=next;a.Mesh.LookAt(next+a.Velocity);}}}
 void PrimitiveWeaponModel(Node3D n,int id,bool hands){if(id>=22){BladeModel(n,id,hands);return;}bool bow=ExpeditionGame.IsBow(id),spear=id is 11 or 16;var wood=new Color(.37f,.25f,.14f);if(bow){for(int i=0;i<12;i++){float a=(i/12f-.5f)*2.5f,b=((i+1)/12f-.5f)*2.5f;Tube(n,new(Mathf.Cos(a)*.24f-.22f,Mathf.Sin(a)*.65f,-.35f),new(Mathf.Cos(b)*.24f-.22f,Mathf.Sin(b)*.65f,-.35f),id==12?.02f:.03f,id==12?wood:Steel);}Tube(n,new(-.145f,-.616f,-.35f),new(-.145f,.616f,-.35f),.004f,Cloth);Tube(n,new(0,0,.05f),new(0,0,-.95f),.008f,Wood);if(id==19)Bevel(n,new(0,-.06f,.05f),new(.11f,.16f,.45f),Wood);}
 else if(id==9)Ellipsoid(n,new(0,0,-.2f),new(.12f,.09f,.16f),new(.43f,.44f,.39f));else if(id==17){Bevel(n,new(0,-.02f,-.2f),new(.22f,.24f,.34f),new(.68f,.37f,.12f));Bevel(n,new(0,0,-.65f),new(.035f,.14f,.65f),Steel);for(int i=0;i<14;i++)Box(n,new(0,(i%2==0?1:-1)*.09f,-.34f-i*.042f),new(.05f,.05f,.025f),Ink);Tube(n,new(-.14f,0,-.14f),new(-.14f,.2f,-.14f),.025f,Ink);Tube(n,new(-.14f,.2f,-.14f),new(.14f,.2f,-.14f),.025f,Ink);}
 else{if(id==10)Ellipsoid(n,new(0,.02f,-.72f),new(.09f,.09f,.23f),wood);if(id==13)Tube(n,new(0,-.02f,-.5f),new(0,.05f,-1.02f),.07f,new(.48f,.33f,.18f),.045f);float length=spear?1.8f:id==8?.8f:1.05f;Tube(n,new(0,-.18f,.05f),new(0,.05f,-length),id is 13 or 10?.047f:.026f,id is 15 or 16?Steel:wood);if(spear){var tip=Bevel(n,new(0,.07f,-length-.09f),new(.10f,.025f,.23f),id==11?new(.43f,.44f,.39f):Steel);tip.RotationDegrees=new(0,0,45);}if(id is 14 or 21)Bevel(n,new(0,.04f,-length+.04f),new(id==21?.30f:.22f,.12f,.13f),Steel);if(id==20)Bevel(n,new(0,.04f,-.75f),new(.04f,.14f,.65f),Steel);for(int i=0;i<5;i++)Tube(n,new(-.03f,-.17f+i*.015f,-i*.03f),new(.03f,-.17f+i*.015f,-i*.03f),.008f,Cloth);}
 if(hands)RebuiltFirstPersonArms(n,false);}
